#!/bin/bash
set -eu
export PATH=/home/loosqk/.cargo/bin:/home/loosqk/.local/bin:$PATH
export PYTHONDONTWRITEBYTECODE=1
quality_python=$(uv python find 3.12)
exec "$quality_python" - <<'PYREMOTE'
from pathlib import Path
import base64,hashlib,json,subprocess
base=Path('/home/loosqk/robot-checks/h2-right-r2-commit-quality-20261010-r1')
source=Path('/home/loosqk/robot-checks/h2-exit-observation-20261009-r1/source')
head=subprocess.check_output(['git','rev-parse','HEAD'],cwd=source,text=True).strip()
status=subprocess.check_output(['git','status','--porcelain=v1','--untracked-files=all'],cwd=source)
if head!='894084738d95a7239611c2b8fbecfe081d3a7fc9' or status: raise ValueError('独立894源码不匹配或非clean')
expected={Path('/home/loosqk/robot-checks/h2-right-ready-20261009-r1/bootstrap/run_release_v2.py'):'d6b20da28de8d5ae077a93cb2fb5ba7f27a66b8145df9e7e91951cb14ac0b12b',source/'scripts/post_e_h2_artifacts.py':'bd2b3f7bb8527cd9ecec73894171638e9cf378656b89e284a585c3baa37b8731'}
for path,sha in expected.items():
 if hashlib.sha256(path.read_bytes()).hexdigest()!=sha: raise ValueError('既有复用模块身份不同')
base.mkdir()
bootstrap=base/'bootstrap';bootstrap.mkdir()
files={'commit_quality_once_r1.py': '', 'commit_quality_run_r1.sh': ''}
for name,value in files.items():
 data=base64.b64decode(value)
 with (bootstrap/name).open('xb') as stream:stream.write(data)
 print(json.dumps({'path':str(bootstrap/name),'sha256':hashlib.sha256(data).hexdigest(),'bytes':len(data)},ensure_ascii=False))
print(json.dumps({'head':head,'clean':status==b'','base':str(base),'tmux':subprocess.check_output(['tmux','-V'],text=True).strip()},ensure_ascii=False))
PYREMOTE
